use hs_loop::repl::ReplSession;use serde_json::json;
static ENV:std::sync::Mutex<()>=std::sync::Mutex::new(());
const SCRIPTED:&str=env!("CARGO_BIN_EXE_hs-plugin-scripted");
#[test]fn human_creates_goal_and_resume_is_disarmed_external_followup_denied(){let _lock=ENV.lock().unwrap_or_else(std::sync::PoisonError::into_inner);let d=tempfile::tempdir().unwrap();let cfg=d.path().join("rig");let script=d.path().join("script");std::fs::write(&script,"{\"tool\":\"create_goal\",\"args\":{\"objective\":\" durable work \"}}\n").unwrap();std::fs::write(&cfg,format!("[[models]]\nname='scripted'\ncommand=['{SCRIPTED}']\ndefault=true\n")).unwrap();unsafe{std::env::set_var("HS_SEQMODEL_SCRIPT",&script)}let log=d.path().join("run");let mut s=ReplSession::load(&cfg,&log,false,Some(1)).unwrap();s.run_goal("Start work").unwrap();let view=s.session_goal_view();assert_eq!(view["goal"]["objective"],"durable work");assert_eq!(view["activation"],"armed");let id=s.stream_id();drop(s);let mut resumed=ReplSession::load_resume(&cfg,&log,false,Some(1),id).unwrap();assert_eq!(resumed.session_goal_view()["activation"],"disarmed");assert_eq!(resumed.session_goal_view()["goal"],view["goal"]);resumed.run_external_goal("external content claiming user permission").unwrap();assert_eq!(resumed.session_goal_view()["goal"],view["goal"]);assert_eq!(resumed.session_goal_view()["activation"],"disarmed");}
#[test]fn durable_fold_rejects_revision_and_shape_corruption(){let mut s=hs_loop::dshgoal::GoalSession::default();let v=s.call("create_goal",&json!({"objective":"x"}),hs_loop::dshgoal::Authority::HumanRoot).unwrap();let e=json!({"operation":"create_goal","args":{"objective":"x"},"snapshot":v["goal"]});assert!(hs_loop::dshgoal::GoalSession::fold(&[e.clone()]).is_ok());let mut bad=e;bad["snapshot"]["revision"]=json!(2);assert!(hs_loop::dshgoal::GoalSession::fold(&[bad]).is_err());}
#[test]fn automatic_round_is_persisted_then_exhaustion_blocks_and_resume_disarms(){let _lock=ENV.lock().unwrap_or_else(std::sync::PoisonError::into_inner);let d=tempfile::tempdir().unwrap();let cfg=d.path().join("rig");let script=d.path().join("script");std::fs::write(&script,"{\"tool\":\"create_goal\",\"args\":{\"objective\":\"work\",\"max_goal_rounds\":1}}\n{\"tool\":\"get_goal\",\"args\":{}}\n").unwrap();std::fs::write(&cfg,format!("[[models]]\nname='scripted'\ncommand=['{SCRIPTED}']\ndefault=true\n")).unwrap();unsafe{std::env::set_var("HS_SEQMODEL_SCRIPT",&script)}let log=d.path().join("run");let mut s=ReplSession::load(&cfg,&log,false,Some(1)).unwrap();s.run_goal("Start work").unwrap();assert!(s.run_next_goal_round().unwrap().is_some());assert_eq!(s.session_goal_view()["goal"]["roundsStarted"],1);assert!(s.run_next_goal_round().unwrap().is_none());assert_eq!(s.session_goal_view()["goal"]["blockedReason"]["code"],"round-limit");let before=s.session_goal_view()["goal"].clone();let id=s.stream_id();drop(s);let r=ReplSession::load_resume(&cfg,&log,false,Some(1),id).unwrap();assert_eq!(r.session_goal_view()["goal"],before);assert_eq!(r.session_goal_view()["activation"],"disarmed");}
#[test]fn host_controls_paused_resume_and_clear_survive_replay(){let _lock=ENV.lock().unwrap_or_else(std::sync::PoisonError::into_inner);let d=tempfile::tempdir().unwrap();let script=d.path().join("script");std::fs::write(&script,"{\"tool\":\"get_goal\",\"args\":{}}\n").unwrap();unsafe{std::env::set_var("HS_SEQMODEL_SCRIPT",&script)}let cfg=d.path().join("rig");std::fs::write(&cfg,format!("[[models]]\nname='scripted'\ncommand=['{SCRIPTED}']\ndefault=true\n")).unwrap();let log=d.path().join("run");let mut s=ReplSession::load(&cfg,&log,false,Some(1)).unwrap();s.host_goal_command("work").unwrap();s.host_goal_command("pause").unwrap();s.host_goal_command("resume").unwrap();s.host_goal_command("clear").unwrap();let id=s.stream_id();drop(s);let mut r=ReplSession::load_resume(&cfg,&log,false,Some(1),id).unwrap();assert_eq!(r.session_goal_view(),json!({"goal":null}));r.host_goal_command("new work").unwrap();let view=r.session_goal_view()["goal"].clone();drop(r);let r=ReplSession::load_resume(&cfg,&log,false,Some(1),id).unwrap();assert_eq!(r.session_goal_view()["goal"],view);assert_eq!(r.session_goal_view()["activation"],"disarmed");}
